/* MODULE kn04 · Bước 5 Chọn kênh · Social và content theo nền tảng
   8 bài × 7 câu. Thương hiệu, nền tảng được nêu như ví dụ công khai; mọi con số là MINH HOẠ và tự khớp nhau. */
BAI_ADD({ mod:'kn04', lessons:[

/* ------------------------------------------------------------------ 01 */
{ id:'B:kn04-01', skill:'channel', read:'6 phút', t:'Tiệm bánh nhỏ có cần có mặt trên cả sáu nền tảng?',
  situation:'Chị Hạnh mở tiệm bánh kem ở Biên Hoà, một mình làm content. Chị lập đủ Facebook, TikTok, YouTube, Instagram, Zalo OA và Threads, mỗi nơi đăng cùng một tấm ảnh bánh. Sau ba tháng, 80% đơn vẫn đến từ tin nhắn fanpage và Zalo của khách quen; TikTok có vài video vài trăm lượt xem; YouTube và Threads gần như bỏ trống.',
  concept:{ name:'Mỗi nền tảng một vai',
    body:'Mỗi nền tảng làm tốt một việc khác nhau trên hành trình của khách. <b>TikTok</b> và Reels giỏi đưa bạn tới người lạ (khám phá). <b>Facebook</b> fanpage và nhóm hợp để khách hỏi, xem đánh giá, nhắn đặt hàng. <b>Zalo</b> là kênh giữ chân khách đã mua: nhắc lịch, báo mẫu mới. <b>YouTube</b> hợp nội dung dài để khách tìm kiếm và tin tưởng. <b>Instagram</b> là tủ kính hình ảnh; <b>Threads</b> là chỗ trò chuyện bằng chữ. Chọn kênh là giao cho mỗi nơi một vai, rồi chỉ giữ những vai bạn đủ sức làm tốt.' },
  example:'Tiệm chị Hạnh cần hai việc: có thêm khách mới trong bán kính 5 km và giữ khách cũ đặt lại sinh nhật. Chị giữ ba vai: TikTok để khám phá (quay cảnh làm bánh), fanpage để chốt đơn và gom đánh giá, Zalo để nhắc khách cũ trước ngày sinh nhật con họ. YouTube, Instagram, Threads tạm dừng. Thời gian làm content không đổi, nhưng mỗi kênh còn lại có nội dung đúng vai của nó.',
  takeaway:'Đừng hỏi nên có mặt ở đâu; hãy hỏi mỗi nơi làm vai gì cho khách, rồi chỉ giữ vai bạn làm nổi.',
  apply:'Viết một bảng ba cột: nền tảng, vai (khám phá, chốt đơn, giữ chân, tạo tin), nội dung chính. Nói trong 60 giây vì sao bạn bỏ bớt một kênh.',
  mistakes:['Mở tài khoản ở mọi nền tảng rồi đăng cùng một thứ ở tất cả.','Chọn kênh theo trào lưu thay vì theo việc khách cần làm ở đó.'],
  q:[
  { type:'mcq', stem:'Đoán trước: một người làm content một mình, đăng cùng một ảnh lên sáu nền tảng. Điều gì dễ xảy ra nhất?',
    options:[{k:'a',t:'Lượt tiếp cận cộng dồn gấp sáu lần so với chỉ đăng một nơi, vì mỗi nơi có tệp khán giả riêng'},{k:'b',t:'Mỗi nơi đều èo uột vì nội dung không hợp cách xem ở đó'},
             {k:'c',t:'Nền tảng sẽ phạt tài khoản vì đăng trùng nội dung ở nơi khác'},{k:'d',t:'Kênh có nhiều người dùng nhất tự động mang về nhiều đơn nhất'}],
    answer:'b', why:{a:'Tiếp cận không cộng dồn như vậy; nội dung lệch khuôn thì mỗi nơi chỉ nhận một phần nhỏ.',
      b:'Đúng. Cùng một ảnh tĩnh không hợp video dọc của TikTok hay chữ của Threads, nên chỗ nào cũng yếu.',
      c:'Đăng cùng nội dung ở nhiều nơi không phải lỗi; vấn đề là nó không hợp cách xem từng nơi.',
      d:'Nhiều người dùng không có nghĩa khách của bạn đang ở đó với tâm thế mua.'} },
  { type:'mcq', stem:'Bạn là chị Hạnh, chỉ có khoảng 8 giờ mỗi tuần cho content. Bạn chọn làm gì?',
    options:[{k:'a',t:'Giữ đủ sáu kênh nhưng đăng thưa hơn để kênh nào cũng còn sống'},{k:'b',t:'Dồn hết vào TikTok vì đang là nơi dễ lên xu hướng nhất cho ngành ăn uống'},
             {k:'c',t:'Thuê thêm người để làm đủ sáu kênh cho chuyên nghiệp'},{k:'d',t:'Giao vai cho ba kênh: TikTok khám phá, fanpage chốt đơn, Zalo giữ khách'}],
    answer:'d', why:{a:'Sáu kênh thưa thớt vẫn là sáu kênh yếu; thời gian bị chia vụn.',
      b:'Bỏ fanpage và Zalo là bỏ chỗ đang tạo ra 80% đơn.',
      c:'Thêm người chưa giải quyết câu hỏi mỗi kênh làm gì; chi phí tăng trước khi biết kênh nào đáng.',
      d:'Đúng. Ba vai phủ đủ hành trình khám phá, mua, mua lại, vừa sức một người.'} },
  { type:'mcq', stem:'Vai nào hợp nhất với Zalo OA của một tiệm bánh?',
    options:[{k:'a',t:'Nhắc khách đã mua về mẫu mới, lịch đặt trước dịp lễ'},{k:'b',t:'Đăng video ngắn để người lạ trong thành phố khám phá tiệm'},
             {k:'c',t:'Đăng bài dài chia sẻ công thức để lên kết quả tìm kiếm'},{k:'d',t:'Chạy các cuộc tranh luận bằng chữ để tăng độ nhận biết'}],
    answer:'a', why:{a:'Đúng. Zalo mạnh ở chỗ giữ liên lạc với người đã quen; đó là vai giữ chân.',
      b:'Khám phá người lạ là việc TikTok, Reels làm tốt hơn; Zalo ít đưa bạn tới người chưa biết bạn.',
      c:'Nội dung dài để tìm kiếm hợp YouTube hoặc blog hơn.',
      d:'Trò chuyện bằng chữ công khai là đặc trưng của Threads, không phải Zalo.'} },
  { type:'mcq', stem:'Một hãng phần mềm kế toán bán cho chủ doanh nghiệp nhỏ. Khách hay gõ tìm "cách làm báo cáo thuế" trước khi mua. Nên ưu tiên nền tảng nào cho vai tạo tin?',
    options:[{k:'a',t:'Threads, vì chủ doanh nghiệp hay đọc các cuộc trò chuyện ngắn'},{k:'b',t:'Instagram, vì hình ảnh giao diện đẹp sẽ tạo ấn tượng chuyên nghiệp'},
             {k:'c',t:'YouTube, với video hướng dẫn dài khách tự tìm thấy'},{k:'d',t:'TikTok, vì video ngắn luôn có lượt xem cao nhất mọi ngành'}],
    answer:'c', why:{a:'Threads hợp trò chuyện, nhưng khách đang chủ động tìm hướng dẫn chi tiết.',
      b:'Giao diện đẹp không trả lời câu hỏi khách đang tìm.',
      c:'Đúng. Khách chủ động tìm kiếm và cần hướng dẫn kỹ; video dài trên YouTube vừa được tìm thấy vừa tạo tin.',
      d:'Lượt xem cao không đồng nghĩa khớp nhu cầu tìm hiểu sâu trước khi mua phần mềm.'} },
  { type:'mcq', stem:'Một shop thời trang thấy TikTok mang về rất nhiều lượt xem nhưng khách lại nhắn hỏi size, giá qua fanpage. Đọc tình huống này thế nào?',
    options:[{k:'a',t:'TikTok đang thất bại vì không trực tiếp ra đơn'},{k:'b',t:'Hai kênh đang làm đúng hai vai nối nhau: khám phá rồi chốt đơn'},
             {k:'c',t:'Nên chuyển hết ngân sách sang fanpage vì đơn đến từ đó'},{k:'d',t:'Fanpage đang ăn cắp công của TikTok nên phải gộp hai kênh làm một'}],
    answer:'b', why:{a:'Đo TikTok bằng đơn trực tiếp là bắt nó làm vai không phải của nó.',
      b:'Đúng. Khách thấy ở TikTok, sang fanpage hỏi và mua; bỏ khâu nào thì chuỗi đứt.',
      c:'Bỏ TikTok thì fanpage mất nguồn khách mới đổ về.',
      d:'Hai kênh không tranh công; chúng là hai bước liên tiếp của cùng một hành trình.'} },
  { type:'mcq', stem:'Khi nào nên mở thêm một nền tảng mới?',
    options:[{k:'a',t:'Khi có một vai rõ mà kênh hiện tại chưa làm, và đủ sức duy trì'},{k:'b',t:'Khi đối thủ vừa mở tài khoản ở đó và có vẻ đang lên nhanh trong vài tuần gần đây'},
             {k:'c',t:'Khi nền tảng đó mới ra mắt, vì vào sớm dễ có nhiều người theo dõi'},{k:'d',t:'Khi kênh hiện tại chững lại, đổi sang kênh mới cho khí thế mới'}],
    answer:'a', why:{a:'Đúng. Kênh mới phải trả lời được: nó làm vai gì còn trống, và ai làm đều đặn.',
      b:'Đối thủ có thể có khách, nguồn lực và mục tiêu khác bạn.',
      c:'Vào sớm có lợi thế, nhưng không có vai rõ thì chỉ là thêm một kênh bỏ hoang.',
      d:'Kênh chững thường do nội dung; chuyển kênh mang theo nguyên vấn đề đó.'} },
  { type:'mcq', stem:'Một phòng khám nha khoa ở Đà Nẵng. Khách sợ đau, cần tin tưởng trước khi đặt lịch. Cách phân vai nào hợp nhất?',
    options:[{k:'a',t:'Chỉ dùng Zalo vì khách quen hay nhắn qua đó để đặt lịch'},{k:'b',t:'Chỉ dùng TikTok đăng video hài về nha sĩ để được chia sẻ rộng rãi khắp nơi'},
             {k:'c',t:'Dùng Instagram đăng ảnh phòng khám sang trọng làm kênh chính'},{k:'d',t:'Video giải thích quy trình để tạo tin, fanpage gom đánh giá và nhận đặt lịch'}],
    answer:'d', why:{a:'Zalo giữ khách cũ tốt, nhưng người mới chưa có lý do tin để nhắn.',
      b:'Hài giúp được thấy, nhưng không gỡ nỗi sợ đau, là rào cản chính.',
      c:'Ảnh đẹp không trả lời câu hỏi có đau không, bao lâu, bao nhiêu tiền.',
      d:'Đúng. Rào cản là niềm tin; kênh tạo tin và kênh chốt lịch cần đi cùng nhau.'} },
  ]},

/* ------------------------------------------------------------------ 02 */
{ id:'B:kn04-02', skill:'channel', read:'6 phút', t:'Sáng nào cũng ngồi nghĩ hôm nay đăng gì?',
  situation:'Minh phụ trách fanpage một thương hiệu cà phê rang xay ở Buôn Ma Thuột. Mỗi sáng anh mất gần một tiếng nghĩ chủ đề. Nhìn lại 30 bài tháng trước: 14 bài khuyến mãi, 9 bài ảnh ly cà phê đẹp, 7 bài chia sẻ ngẫu hứng. Khách theo dõi không nói được thương hiệu này khác gì những nhà rang khác.',
  concept:{ name:'Trụ cột nội dung (content pillars)',
    body:'Trụ cột nội dung là 3 đến 5 chủ đề cố định mà mọi bài đăng đều thuộc về một trong số đó. Mỗi trụ cột nối với một điều bạn muốn khách nhớ và một nhu cầu thật của khách. Ví dụ một nhà rang có thể có: <b>nguồn gốc hạt</b> (vì sao đáng tin), <b>cách pha tại nhà</b> (giúp khách dùng ngon), <b>người trồng</b> (câu chuyện riêng), <b>ưu đãi</b> (lý do mua ngay). Có trụ cột, việc nghĩ ý tưởng chuyển từ "đăng gì hôm nay" sang "tuần này trụ cột nào còn thiếu", và khách dần nhận ra bạn qua sự lặp lại có chủ đích.' },
  example:'Minh chọn bốn trụ cột và chia 20 bài mỗi tháng: cách pha tại nhà 8 bài, nguồn gốc hạt 5, người trồng 3, ưu đãi 4. Ý tưởng được gom theo trụ cột ngay khi nảy ra, nên sáng thứ Hai anh chỉ mất 15 phút xếp lịch cả tuần. Sau hai tháng, bình luận bắt đầu có câu kiểu "nhà này pha phin chỉ kỹ ghê", đúng điều thương hiệu muốn được nhớ.',
  takeaway:'Ba đến năm trụ cột cố định biến việc nghĩ ý tưởng hằng ngày thành việc lấp chỗ trống có chủ đích.',
  apply:'Viết ba trụ cột cho một thương hiệu bạn thích, mỗi trụ cột một câu nói vì sao khách quan tâm. Nói trong 60 giây.',
  mistakes:['Đặt trụ cột theo định dạng (video, ảnh, meme) thay vì theo chủ đề khách quan tâm.','Có quá nhiều trụ cột nên không trụ nào đủ dày để khách nhớ.'],
  q:[
  { type:'mcq', stem:'Đoán trước: vì sao khách theo dõi fanpage của Minh không nói được thương hiệu khác gì đối thủ?',
    options:[{k:'a',t:'Vì ảnh chưa đủ đẹp so với các nhà rang lớn đang đầu tư studio chụp chuyên nghiệp'},{k:'b',t:'Vì đăng chưa đủ nhiều, cần mỗi ngày ba bài'},
             {k:'c',t:'Vì bài đăng rời rạc, không chủ đề nào lặp đủ để được nhớ'},{k:'d',t:'Vì khách trên mạng không quan tâm tới thương hiệu cà phê'}],
    answer:'c', why:{a:'Ảnh đẹp giúp dừng lướt, nhưng không nói thương hiệu khác ở đâu.',
      b:'Đăng nhiều hơn mà vẫn rời rạc thì chỉ nhiều thêm tiếng ồn.',
      c:'Đúng. Không có chủ đề lặp lại có chủ đích thì khách không có gì để gắn với thương hiệu.',
      d:'Khách vẫn quan tâm cà phê; họ chỉ chưa được cho một lý do nhớ riêng nhà này.'} },
  { type:'mcq', stem:'Bạn là Minh, cần sửa lịch đăng từ tháng sau. Bạn làm gì trước tiên?',
    options:[{k:'a',t:'Chọn 3 đến 5 trụ cột theo điều muốn khách nhớ, rồi chia bài theo trụ cột'},{k:'b',t:'Giữ nguyên chủ đề, đổi sang đăng video vì video đang được ưu tiên hiển thị nhiều'},
             {k:'c',t:'Tăng bài khuyến mãi vì đó là loại bài ra đơn nhanh nhất'},{k:'d',t:'Tìm một mẫu lịch đăng 30 ngày có sẵn trên mạng rồi làm theo'}],
    answer:'a', why:{a:'Đúng. Trụ cột trả lời "đăng gì" một lần cho cả tháng và gắn mọi bài vào điều cần nhớ.',
      b:'Đổi định dạng không giải quyết chuyện nội dung rời rạc.',
      c:'Nhiều khuyến mãi hơn khiến thương hiệu chỉ được nhớ là nơi hay giảm giá.',
      d:'Lịch mẫu không biết thương hiệu của bạn cần được nhớ vì điều gì.'} },
  { type:'calc', stem:'Minh đăng 20 bài/tháng. Trụ cột "cách pha tại nhà" chiếm 8 bài. Trụ cột này chiếm bao nhiêu phần trăm số bài?',
    unit:'%', ans:40, tol:0.1, wrong:[[250,'SAI_MAU_SO'],[26.7,'SAI_MAU_SO']], errors:['SAI_MAU_SO'],
    steps:['Tỉ lệ = số bài của trụ cột ÷ tổng số bài.','8 ÷ 20 = 0,4 = <b>40%</b>.'] },
  { type:'mcq', stem:'Bộ nào dưới đây là trụ cột nội dung đúng nghĩa cho một thương hiệu mỹ phẩm thuần chay?',
    options:[{k:'a',t:'Video, ảnh, meme, livestream'},{k:'b',t:'Thứ Hai, thứ Tư, thứ Sáu, Chủ nhật'},
             {k:'c',t:'Bài viral, bài bán hàng, bài theo trend đang nổi trong tuần'},{k:'d',t:'Thành phần minh bạch, chăm da đúng cách, câu chuyện nguyên liệu'}],
    answer:'d', why:{a:'Đó là định dạng; một video có thể thuộc bất kỳ chủ đề nào.',
      b:'Đó là lịch đăng, không phải chủ đề.',
      c:'Đây là mục đích từng bài, không nói gì về điều khách cần nhớ.',
      d:'Đúng. Mỗi trụ cột là một chủ đề khách quan tâm và nối với định vị thuần chay.'} },
  { type:'mcq', stem:'Một thương hiệu đặt 9 trụ cột, mỗi tháng đăng 18 bài. Vấn đề chính là gì?',
    options:[{k:'a',t:'Chín trụ cột quá ít để có đủ ý tưởng cho cả tháng'},{k:'b',t:'Mỗi trụ cột chỉ khoảng 2 bài/tháng, quá mỏng để khách nhớ'},
             {k:'c',t:'Nhiều trụ cột làm thuật toán khó phân loại trang nên sẽ giảm tiếp cận của mọi bài đăng'},{k:'d',t:'Không có vấn đề, càng đa dạng càng thu hút nhiều nhóm khách'}],
    answer:'b', why:{a:'Chín trụ cột là nhiều, không phải ít; ý tưởng không thiếu mà là bị chia vụn.',
      b:'Đúng. 18 ÷ 9 = 2 bài; lặp quá thưa thì không chủ đề nào thành dấu ấn.',
      c:'Lý do chính là trí nhớ của khách, không phải cách máy phân loại.',
      d:'Đa dạng quá mức làm thương hiệu nhoè, khách không biết bạn giỏi điều gì.'} },
  { type:'mcq', stem:'Làm sao biết một trụ cột nên giữ hay bỏ sau một quý?',
    options:[{k:'a',t:'Giữ trụ cột mà đội thấy dễ làm nhất, vì làm đều quan trọng hơn làm đúng chủ đề'},{k:'b',t:'Bỏ trụ cột có ít lượt thích nhất trong quý vừa qua'},
             {k:'c',t:'Xem trụ cột có giúp khách nhớ đúng điều cần nhớ và có ra hành động mong muốn không'},{k:'d',t:'Giữ hết cả quý sau, vì đổi trụ cột giữa chừng làm khách theo dõi bối rối'}],
    answer:'c', why:{a:'Dễ làm không nói gì về giá trị với khách.',
      b:'Lượt thích thấp có thể vẫn là trụ cột được lưu, được hỏi mua nhiều.',
      c:'Đúng. Trụ cột phục vụ trí nhớ thương hiệu và mục tiêu; đo theo đúng hai thứ đó.',
      d:'Trụ cột không hiệu quả sau một quý thì nên điều chỉnh; giữ vì sợ đổi là tốn công vô ích.'} },
  { type:'mcq', stem:'Một quán bún chả ở Hà Nội muốn khách nhớ "nướng than hoa, thịt ướp mỗi sáng". Trụ cột nào khớp nhất với điều này?',
    options:[{k:'a',t:'Hậu trường bếp: cảnh ướp thịt, nướng than mỗi sáng'},{k:'b',t:'Bắt trend nhạc TikTok đang hot mỗi tuần để lên xu hướng nhanh hơn các quán khác'},
             {k:'c',t:'Ảnh khách nổi tiếng từng ghé quán'},{k:'d',t:'Mã giảm giá cho khách check-in'}],
    answer:'a', why:{a:'Đúng. Trụ cột cho khách thấy tận mắt điều quán muốn được nhớ.',
      b:'Trend giúp được thấy, nhưng không gắn với điều cần nhớ.',
      c:'Người nổi tiếng tạo tò mò, nhưng không chứng minh than hoa hay thịt tươi.',
      d:'Giảm giá kéo khách tới, không xây dấu ấn về cách nấu.'} },
  ]},

/* ------------------------------------------------------------------ 03 */
{ id:'B:kn04-03', skill:'channel', read:'6 phút', t:'Bao nhiêu bài bán hàng thì khách bắt đầu bỏ theo dõi?',
  situation:'Shop đồ gia dụng của Lan ở TP.HCM đăng 30 bài mỗi tháng, trong đó 24 bài là ảnh sản phẩm kèm giá và "inbox ngay". Ba tháng gần đây, lượt tiếp cận mỗi bài giảm dần, bình luận chủ yếu là "giá bao nhiêu" rồi im. Lan định tăng thêm bài giảm giá để cứu doanh số.',
  concept:{ name:'Tỉ lệ nội dung giá trị và nội dung bán hàng',
    body:'Nội dung <b>giá trị</b> giúp khách giải quyết một việc của họ: mẹo dùng, so sánh, hướng dẫn, câu chuyện. Nội dung <b>bán hàng</b> xin khách hành động: mua, nhắn, đặt. Khi gần như mọi bài đều xin, khách coi trang là tờ rơi và lướt qua; ít người tương tác thì nền tảng cũng ít phân phối. Nhiều thương hiệu nhắm quanh mức khoảng 70 đến 80% giá trị, 20 đến 30% bán hàng, nhưng đó chỉ là điểm xuất phát để thử, không phải luật. Điều quan trọng là bài giá trị phải dẫn tự nhiên về sản phẩm.' },
  example:'Lan chuyển sang 30 bài gồm 21 bài giá trị (mẹo bảo quản đồ ăn, so sánh hộp thuỷ tinh với nhựa, video dọn tủ lạnh 5 phút) và 9 bài bán hàng. Mỗi bài mẹo đều dùng đúng sản phẩm của shop. Sau hai tháng, bài bán hàng ít hơn nhưng mỗi bài nhận nhiều tin nhắn hơn, vì người xem đã quen trang và tin lời khuyên của shop.',
  takeaway:'Bài giá trị cho khách lý do ở lại; bài bán hàng chỉ hiệu quả khi khách đã có lý do đó.',
  apply:'Lấy 10 bài gần nhất của một trang bạn theo dõi, đánh dấu giá trị hay bán hàng, tính tỉ lệ. Nói trong 60 giây trang đó nên đổi gì.',
  mistakes:['Tưởng bài giá trị là bài không liên quan sản phẩm.','Áp cứng tỉ lệ 80/20 mà không thử và đo trên chính trang của mình.'],
  q:[
  { type:'mcq', stem:'Đoán trước: Lan tăng thêm bài giảm giá khi tiếp cận đang giảm. Điều gì dễ xảy ra?',
    options:[{k:'a',t:'Doanh số bật lên ngay và bền vững vì khách thích giảm giá hơn mọi loại nội dung'},{k:'b',t:'Tiếp cận tăng vì bài giảm giá luôn được chia sẻ nhiều'},
             {k:'c',t:'Không thay đổi gì vì khách đã quen với trang'},{k:'d',t:'Có thể tăng đơn ngắn hạn nhưng trang càng giống tờ rơi, khách càng lướt qua'}],
    answer:'d', why:{a:'Giảm giá kéo đơn tạm thời nhưng không sửa lý do khách ngừng xem.',
      b:'Bài giảm giá được chia sẻ khi thật hấp dẫn; dày đặc thì thành nhàm.',
      c:'Thêm bài bán hàng làm khách phản ứng, thường theo hướng lướt qua nhanh hơn.',
      d:'Đúng. Đơn có thể nhích lên, nhưng trang càng mất lý do để người ta dừng lại xem.'} },
  { type:'mcq', stem:'Bạn là Lan. Bạn chọn cách sửa nào cho tháng tới?',
    options:[{k:'a',t:'Bỏ hết bài bán hàng một tháng để khách quên hình ảnh tờ rơi'},{k:'b',t:'Chuyển phần lớn sang bài mẹo dùng chính sản phẩm, giữ khoảng 30% bài bán hàng'},
             {k:'c',t:'Giữ số bài bán hàng, chỉ thêm ảnh đẹp hơn và thêm biểu tượng cảm xúc cho sinh động'},{k:'d',t:'Đăng bài giải trí không liên quan để kéo tương tác'}],
    answer:'b', why:{a:'Bỏ hẳn bài bán hàng thì mất đơn mà không cần thiết.',
      b:'Đúng. Bài giá trị dùng chính sản phẩm vừa giúp khách vừa giới thiệu hàng; vẫn còn bài để chốt đơn.',
      c:'Đẹp hơn vẫn là tờ rơi; khách không có lý do mới để dừng lại.',
      d:'Tương tác từ nội dung lạc đề không dẫn về sản phẩm và làm nhoè trang.'} },
  { type:'calc', stem:'Một trang đăng 30 bài/tháng, muốn nội dung giá trị chiếm 70%. Số bài bán hàng tối đa mỗi tháng là bao nhiêu?',
    unit:'bài', ans:9, tol:0, wrong:[[21,'SAI_TINH_TOAN'],[7,'NHAM_DIEM_PHAN_TRAM']], errors:['SAI_TINH_TOAN','NHAM_DIEM_PHAN_TRAM'],
    steps:['Bài bán hàng chiếm 100% − 70% = 30%.','30 × 30% = <b>9 bài</b>.'] },
  { type:'mcq', stem:'Bài nào dưới đây là bài giá trị nhưng vẫn dẫn tự nhiên về sản phẩm của một shop chảo chống dính?',
    options:[{k:'a',t:'Video "3 lỗi làm chảo chống dính nhanh bong" dùng chảo của shop'},{k:'b',t:'Ảnh chảo trên nền trắng với giá giảm 20% chỉ trong hôm nay'},
             {k:'c',t:'Meme vui về chuyện nấu ăn không liên quan tới chảo'},{k:'d',t:'Bài kể về ngày thành lập shop và lời cảm ơn khách hàng thân thiết suốt ba năm qua'}],
    answer:'a', why:{a:'Đúng. Khách học được điều hữu ích, và sản phẩm xuất hiện đúng lúc họ đang nghĩ về chảo.',
      b:'Đây là bài bán hàng thuần.',
      c:'Vui, nhưng không dẫn về sản phẩm nên khó chuyển thành đơn.',
      d:'Bài cảm ơn có thể ấm áp, nhưng không giúp khách giải quyết việc gì của họ.'} },
  { type:'mcq', stem:'Một trang có 50% bài bán hàng nhưng tiếp cận và tin nhắn vẫn tăng đều. Nên làm gì?',
    options:[{k:'a',t:'Hạ ngay xuống 20% bài bán hàng vì đó là tỉ lệ chuẩn mà các trang lớn đều áp dụng'},{k:'b',t:'Tăng lên 80% bài bán hàng vì đang hiệu quả'},
             {k:'c',t:'Giữ tỉ lệ, tiếp tục theo dõi, vì tỉ lệ là điểm xuất phát, số liệu mới là thước đo'},{k:'d',t:'Ngừng đăng bài giá trị vì khách trang này chỉ quan tâm giá'}],
    answer:'c', why:{a:'Không có tỉ lệ chuẩn cho mọi trang; số liệu thật đang nói trang ổn.',
      b:'Đẩy mạnh tới 80% là suy diễn quá xa từ dữ kiện hiện có.',
      c:'Đúng. Tỉ lệ gợi ý chỉ để bắt đầu; khi dữ liệu tốt thì giữ và quan sát.',
      d:'Chưa có dữ kiện cho thấy bài giá trị vô ích.'} },
  { type:'mcq', stem:'Vì sao trang toàn bài bán hàng thường bị giảm tiếp cận theo thời gian?',
    options:[{k:'a',t:'Vì nền tảng cấm bài có giá và số điện thoại'},{k:'b',t:'Vì bài bán hàng luôn bị gắn nhãn quảng cáo và chỉ hiện với người đã trả tiền'},
             {k:'c',t:'Vì khách theo dõi đã mua hết nên không còn ai để tiếp cận'},{k:'d',t:'Vì ít người dừng lại tương tác, nền tảng hiểu bài ít hấp dẫn và phân phối ít đi'}],
    answer:'d', why:{a:'Có giá và số điện thoại không bị cấm; vấn đề là phản ứng của người xem.',
      b:'Bài thường của trang không tự thành quảng cáo trả tiền.',
      c:'Người theo dõi chưa mua vẫn còn nhiều; họ chỉ lướt qua.',
      d:'Đúng. Phản ứng yếu lặp lại khiến nền tảng phân phối bài của trang cho ít người hơn.'} },
  { type:'mcq', stem:'Một trung tâm tiếng Anh cho trẻ em. Bài nào nên là phần lớn nội dung?',
    options:[{k:'a',t:'Bảng học phí và ưu đãi đăng ký sớm'},{k:'b',t:'Trò chơi tiếng Anh 5 phút phụ huynh làm cùng con tại nhà'},
             {k:'c',t:'Ảnh chụp cơ sở vật chất mới và phòng học được trang trí đẹp, nhiều màu sắc'},{k:'d',t:'Thông báo lịch khai giảng các lớp mới'}],
    answer:'b', why:{a:'Học phí cần có, nhưng là bài bán hàng; dày đặc thì phụ huynh lướt qua.',
      b:'Đúng. Phụ huynh nhận được thứ dùng ngay, và thấy cách trung tâm dạy.',
      c:'Ảnh cơ sở vật chất tạo ấn tượng một lần, không giúp phụ huynh việc gì.',
      d:'Lịch khai giảng là thông báo bán hàng, nên chiếm phần nhỏ.'} },
  ]},

/* ------------------------------------------------------------------ 04 */
{ id:'B:kn04-04', skill:'measure', read:'7 phút', t:'Mười nghìn lượt thích, sao không ai nhắn mua?',
  situation:'Một thương hiệu nước mắm ở Phú Quốc tổ chức minigame "like, share, tag 3 bạn bè để nhận quà". Bài đạt 10.000 lượt thích, 6.000 bình luận, tiếp cận 80.000 người. Tuần đó chỉ có 12 đơn, gần như bằng tuần thường. Bình luận toàn là tag tên, nhiều tài khoản chuyên săn quà.',
  concept:{ name:'Tương tác thật và tương tác ảo',
    body:'Tương tác <b>thật</b> đến từ người quan tâm tới sản phẩm: bình luận hỏi chi tiết, lưu bài để làm theo, chia sẻ cho người cần, nhắn tin hỏi mua. Tương tác <b>ảo</b> là con số không đi kèm quan tâm: tài khoản săn quà, lượt thích mua, nhóm đổi tương tác chéo. Ảo không chỉ vô ích mà còn gây hại: nền tảng học rằng nội dung của bạn hợp với người săn quà và phân phối tiếp cho họ, còn bạn tưởng mình đang thành công. Hãy đọc tương tác theo chất lượng, không theo tổng.' },
  example:'Tách bình luận bài minigame: 5.800 là tag tên, chỉ 200 có câu hỏi về vị, độ đạm, cách giao. So với một bài thường "cách pha nước chấm bánh xèo": 900 lượt thích, 60 bình luận nhưng 45 là câu hỏi, 350 lượt lưu, 30 tin nhắn hỏi mua. Bài nhỏ này mang về nhiều khách tiềm năng hơn bài minigame lớn gấp hơn mười lần.',
  takeaway:'Đếm người quan tâm, đừng đếm lượt bấm: một câu hỏi thật giá trị hơn một trăm lượt tag bạn bè.',
  apply:'Mở bài có nhiều tương tác nhất của một trang, đọc 30 bình luận đầu, đếm bao nhiêu câu thể hiện quan tâm thật. Nói kết quả trong 60 giây.',
  mistakes:['Báo cáo tổng tương tác mà không tách loại tương tác.','Mua lượt thích hoặc tham gia nhóm đổi tương tác để trang trông sôi động.'],
  q:[
  { type:'mcq', stem:'Đoán trước: vì sao minigame 10.000 lượt thích lại chỉ ra 12 đơn?',
    options:[{k:'a',t:'Phần lớn người tham gia đến vì quà, không quan tâm sản phẩm'},{k:'b',t:'Vì giá nước mắm quá cao so với mặt bằng'},
             {k:'c',t:'Vì minigame chạy chưa đủ lâu để đơn kịp về; thường phải một đến hai tháng sau đơn mới tăng mạnh'},{k:'d',t:'Vì nền tảng ẩn bài minigame khỏi người thật'}],
    answer:'a', why:{a:'Đúng. Bình luận toàn tag tên là dấu hiệu người đến vì quà.',
      b:'Giá không đổi so với tuần thường, mà tuần thường vẫn có số đơn tương tự.',
      c:'Không có dữ kiện cho thấy đơn sẽ đến muộn; người săn quà hiếm khi quay lại mua.',
      d:'Bài đã tiếp cận 80.000 người; vấn đề là ai được tiếp cận.'} },
  { type:'mcq', stem:'Bạn là marketer thương hiệu nước mắm, sếp muốn làm tiếp minigame mỗi tháng. Bạn đề xuất gì?',
    options:[{k:'a',t:'Làm tiếp nhưng tăng giá trị giải thưởng lên gấp đôi để thu hút nhiều người hơn nữa'},{k:'b',t:'Làm tiếp như cũ vì lượt thích giúp trang trông uy tín'},
             {k:'c',t:'Đổi thước đo sang câu hỏi, lượt lưu, tin nhắn hỏi mua; thử nội dung hướng dẫn nấu'},{k:'d',t:'Dừng mọi hoạt động social, chuyển sang bán ở chợ'}],
    answer:'c', why:{a:'Giải to hơn kéo thêm người săn quà, càng lệch tệp.',
      b:'Trông uy tín không thành đơn, lại dạy nền tảng phân phối sai người.',
      c:'Đúng. Đo đúng tín hiệu quan tâm và tạo nội dung thu hút người nấu ăn thật.',
      d:'Social vẫn hiệu quả ở bài hướng dẫn; bỏ cả kênh là phản ứng quá mức.'} },
  { type:'calc', stem:'Bài minigame có 6.000 bình luận, trong đó 5.800 chỉ là tag tên. Bình luận có câu hỏi thật chiếm bao nhiêu phần trăm?',
    unit:'%', ans:3.33, tol:0.05, wrong:[[96.67,'SAI_TINH_TOAN'],[200,'NHAM_SO_TUYET_DOI']], errors:['SAI_TINH_TOAN','NHAM_SO_TUYET_DOI'],
    steps:['Bình luận thật = 6.000 − 5.800 = 200.','200 ÷ 6.000 ≈ <b>3,33%</b>.'] },
  { type:'mcq', stem:'Tín hiệu nào cho thấy tương tác thật rõ nhất với một shop bán giày chạy bộ?',
    options:[{k:'a',t:'Nhiều biểu tượng thả tim từ tài khoản không ảnh đại diện'},{k:'b',t:'Bình luận hỏi "chân bè 42 đi size nào, chạy đường nhựa có êm không"'},
             {k:'c',t:'Bình luận "hay quá shop ơi" lặp lại ở rất nhiều bài khác nhau từ cùng một nhóm tài khoản'},{k:'d',t:'Số người theo dõi tăng 5.000 trong một đêm'}],
    answer:'b', why:{a:'Tài khoản không ảnh đại diện là dấu hiệu ảo phổ biến.',
      b:'Đúng. Câu hỏi cụ thể về size và cách dùng cho thấy người đang cân nhắc mua.',
      c:'Lặp lại chung chung từ cùng nhóm là dấu hiệu đổi tương tác chéo.',
      d:'Tăng vọt bất thường trong một đêm thường là người theo dõi mua hoặc ảo.'} },
  { type:'mcq', stem:'Vì sao tương tác ảo có thể làm hại trang về lâu dài, chứ không chỉ vô ích?',
    options:[{k:'a',t:'Vì bị phạt tiền theo số lượt thích ảo'},{k:'b',t:'Vì người theo dõi thật sẽ tự động bị xoá khỏi trang'},
             {k:'c',t:'Vì khách thật sẽ thấy danh sách tài khoản ảo trong phần thống kê của trang và mất lòng tin'},{k:'d',t:'Vì nền tảng học theo phản ứng, rồi đưa bài tới thêm người không quan tâm'}],
    answer:'d', why:{a:'Không có cơ chế phạt tiền theo lượt thích như vậy.',
      b:'Người theo dõi thật không bị xoá vì có ảo.',
      c:'Khách không xem được thống kê nội bộ của trang.',
      d:'Đúng. Nền tảng tìm người giống những ai đã tương tác, nên tệp ảo kéo theo phân phối sai.'} },
  { type:'mcq', stem:'Một quán cà phê sách có bài đạt 300 lượt thích, 80 lượt lưu, 15 lượt chia sẻ kèm câu "cuối tuần đi chỗ này". So với bài 2.000 lượt thích, 5 lượt lưu, nên đánh giá thế nào?',
    options:[{k:'a',t:'Bài 300 lượt thích cho thấy quan tâm thật cao hơn nhờ lưu và chia sẻ có ý định đi'},{k:'b',t:'Bài 2.000 lượt thích tốt hơn vì tổng tương tác cao gấp nhiều lần'},
             {k:'c',t:'Không so được vì hai bài đăng vào hai ngày khác nhau trong tuần, lượng người online khác'},{k:'d',t:'Hai bài như nhau vì đều có tương tác'}],
    answer:'a', why:{a:'Đúng. Lưu và chia sẻ kèm ý định là tín hiệu người muốn đến thật.',
      b:'Tổng lượt thích cao không cho biết ai có ý định đến quán.',
      c:'Khác ngày có ảnh hưởng, nhưng khoảng cách về lượt lưu quá lớn để bỏ qua.',
      d:'Loại tương tác khác nhau nói những điều khác nhau.'} },
  { type:'mcq', stem:'Một nhân viên đề nghị tham gia nhóm "đổi tương tác chéo" để trang trông sôi động. Lý do đúng nhất để từ chối là gì?',
    options:[{k:'a',t:'Tốn thời gian vào nhóm và bấm thích cho người khác mỗi ngày, ảnh hưởng tới việc làm nội dung'},{k:'b',t:'Nhóm đổi tương tác thường thu phí rất cao'},
             {k:'c',t:'Người tương tác không phải khách, làm số liệu sai và dạy nền tảng phân phối sai'},{k:'d',t:'Trang sẽ bị khoá ngay lập tức'}],
    answer:'c', why:{a:'Tốn thời gian là thật, nhưng hại lớn hơn nằm ở số liệu và phân phối.',
      b:'Nhiều nhóm miễn phí; vấn đề không phải chi phí.',
      c:'Đúng. Bạn mất khả năng đọc số liệu thật, và bài bị đưa tới sai người.',
      d:'Không chắc bị khoá ngay; đừng dựa vào lời đe doạ không chắc chắn.'} },
  ]},

/* ------------------------------------------------------------------ 05 */
{ id:'B:kn04-05', skill:'measure', read:'7 phút', t:'Bài nào thắng khi bài tiếp cận cao lại ít người lưu?',
  situation:'Đội content của một thương hiệu thực phẩm healthy tổng kết tháng. Video A (clip hài) tiếp cận 120.000 người, 240 lượt lưu, 60 lượt bấm link. Video B (thực đơn 7 ngày giảm cân) tiếp cận 30.000 người, 1.500 lượt lưu, 450 lượt bấm link. Trưởng nhóm muốn làm thêm clip hài vì "A thắng tiếp cận".',
  concept:{ name:'Đo nội dung theo mục tiêu',
    body:'Mỗi bài có một việc chính, và mỗi việc có chỉ số riêng. Muốn được biết đến: nhìn <b>tiếp cận</b> và lượt xem hết. Muốn khách thấy hữu ích, sẽ quay lại: nhìn <b>tỉ lệ lưu</b>. Muốn được lan truyền: nhìn <b>tỉ lệ chia sẻ</b>. Muốn dẫn tới mua: nhìn <b>tỉ lệ bấm link</b> hoặc tin nhắn. Hãy chia chỉ số cho số người tiếp cận để so công bằng giữa bài lớn và bài nhỏ. So hai bài bằng một con số duy nhất sẽ luôn khiến bạn làm thêm loại nội dung sai mục tiêu.' },
  example:'Tính theo tỉ lệ: A lưu 240 ÷ 120.000 = 0,2%, bấm link 0,05%. B lưu 1.500 ÷ 30.000 = 5%, bấm link 1,5%. Mục tiêu tháng này là đưa khách về trang bán hàng, nên B thắng rõ. A vẫn có ích nếu mục tiêu là nhận biết, nhưng không nên nhân bản khi cần đơn.',
  takeaway:'Chọn chỉ số theo việc của bài, rồi chia cho tiếp cận trước khi so.',
  apply:'Chọn hai bài của một trang, ghi mục tiêu từng bài, chỉ số tương ứng và tỉ lệ trên tiếp cận. Nói trong 60 giây bài nào thắng.',
  mistakes:['So bài bằng tổng tiếp cận dù mục tiêu là bán hàng.','So số tuyệt đối giữa bài tiếp cận khác nhau nhiều lần.'],
  q:[
  { type:'mcq', stem:'Đoán trước: nếu mục tiêu là đưa khách về trang bán hàng, bài nào thắng?',
    options:[{k:'a',t:'Video A, vì tiếp cận gấp bốn lần thì sớm muộn cũng ra nhiều khách hơn'},{k:'b',t:'Video B, vì tỉ lệ bấm link cao hơn A rất nhiều'},
             {k:'c',t:'Hoà, vì mỗi bài mạnh một chỉ số'},{k:'d',t:'Chưa kết luận được khi chưa biết doanh thu từng bài'}],
    answer:'b', why:{a:'Tiếp cận lớn nhưng hầu như không ai bấm link.',
      b:'Đúng. Với mục tiêu này, bấm link là chỉ số chính, và B vượt cả về số tuyệt đối lẫn tỉ lệ.',
      c:'Khi đã có mục tiêu thì không hoà; chỉ số khớp mục tiêu quyết định.',
      d:'Doanh thu cho thêm thông tin, nhưng dữ liệu bấm link đã đủ để quyết định sơ bộ.'} },
  { type:'mcq', stem:'Bạn là trưởng nhóm, tháng tới cần tăng đơn từ trang bán hàng. Bạn chọn gì?',
    options:[{k:'a',t:'Làm thêm clip hài vì tiếp cận lớn sẽ kéo tăng người theo dõi và gián tiếp đưa đơn về'},{k:'b',t:'Chia đều hai loại để an toàn'},
             {k:'c',t:'Ngừng hẳn clip hài vì không ra đơn'},{k:'d',t:'Làm thêm nội dung kiểu B, đo bằng tỉ lệ lưu và bấm link; giữ ít clip hài cho nhận biết'}],
    answer:'d', why:{a:'Tiếp cận lớn không chuyển thành bấm link ở loại nội dung này.',
      b:'Chia đều bỏ qua dữ liệu đang chỉ rõ loại nào khớp mục tiêu.',
      c:'Clip hài vẫn có vai nhận biết; bỏ hẳn là cực đoan.',
      d:'Đúng. Dồn nguồn lực theo mục tiêu, vẫn giữ một phần cho vai khác.'} },
  { type:'calc', stem:'Video B tiếp cận 30.000 người và có 1.500 lượt lưu. Tỉ lệ lưu trên tiếp cận là bao nhiêu phần trăm?',
    unit:'%', ans:5, tol:0.05, wrong:[[2000,'SAI_MAU_SO'],[1.25,'SAI_MAU_SO']], errors:['SAI_MAU_SO'],
    steps:['Tỉ lệ lưu = lượt lưu ÷ tiếp cận.','1.500 ÷ 30.000 = 0,05 = <b>5%</b>.'] },
  { type:'mcq', stem:'Một trang muốn được nhiều người mới biết đến qua truyền miệng. Chỉ số nào nên theo dõi chính?',
    options:[{k:'a',t:'Tỉ lệ bấm link về trang bán hàng'},{k:'b',t:'Số người theo dõi tăng thêm trong tuần tính từ lúc đăng bài'},
             {k:'c',t:'Tỉ lệ chia sẻ trên tiếp cận'},{k:'d',t:'Số tin nhắn hỏi giá'}],
    answer:'c', why:{a:'Bấm link đo ý định mua, không đo lan truyền.',
      b:'Người theo dõi tăng có nhiều nguồn, không cho biết bài có được chuyền tay không.',
      c:'Đúng. Chia sẻ là hành động đưa bài tới người mới qua tay người quen.',
      d:'Tin nhắn hỏi giá là tín hiệu mua, không phải lan truyền.'} },
  { type:'mcq', stem:'Bài X tiếp cận 5.000, được lưu 200. Bài Y tiếp cận 50.000, được lưu 600. Bài nào khách thấy hữu ích hơn?',
    options:[{k:'a',t:'Bài X, vì tỉ lệ lưu 4% so với 1,2%'},{k:'b',t:'Bài Y, vì số lượt lưu nhiều gấp ba lần bài X'},
             {k:'c',t:'Như nhau, vì cả hai đều có người lưu lại để xem sau'},{k:'d',t:'Không so được vì tiếp cận chênh nhau quá nhiều lần'}],
    answer:'a', why:{a:'Đúng. 200 ÷ 5.000 = 4%, 600 ÷ 50.000 = 1,2%; mỗi người thấy X có khả năng lưu cao hơn nhiều.',
      b:'Số tuyệt đối cao vì Y được thấy nhiều hơn, không phải vì hữu ích hơn.',
      c:'Tỉ lệ chênh hơn ba lần, không thể coi là như nhau.',
      d:'Chính vì chênh tiếp cận nên phải so bằng tỉ lệ, và tỉ lệ so được.'} },
  { type:'mcq', stem:'Vì sao lượt lưu thường là tín hiệu đáng tin cho nội dung hướng dẫn?',
    options:[{k:'a',t:'Vì lượt lưu được nền tảng công khai cho mọi người xem nên tạo uy tín xã hội'},{k:'b',t:'Người lưu định quay lại dùng, tức bài có giá trị thực tế với họ'},
             {k:'c',t:'Vì lưu tốn ít công hơn bình luận'},{k:'d',t:'Vì lưu luôn dẫn tới mua hàng trong vòng một tuần'}],
    answer:'b', why:{a:'Nhiều nền tảng không công khai lượt lưu như lượt thích.',
      b:'Đúng. Lưu là hành động dành cho sau này, dấu hiệu bài giúp được việc thật.',
      c:'Dễ làm không làm cho tín hiệu đáng tin hơn.',
      d:'Lưu không đảm bảo mua; nó đo mức hữu ích.'} },
  { type:'mcq', stem:'Một chuỗi gym ra mắt chi nhánh mới ở Cần Thơ, tháng đầu cần người trong vùng biết tới. Nên đánh giá video giới thiệu bằng gì?',
    options:[{k:'a',t:'Số đơn đăng ký gói năm ngay trong tháng'},{k:'b',t:'Số lượt lưu bài tập mẫu'},
             {k:'c',t:'Số bình luận khen video quay đẹp và nhạc nền bắt tai từ người xem khắp nơi trên cả nước'},{k:'d',t:'Tiếp cận và lượt xem hết trong nhóm người ở Cần Thơ'}],
    answer:'d', why:{a:'Đăng ký gói năm là mục tiêu sau; tháng đầu cần được biết trước.',
      b:'Lưu bài tập đo hữu ích, không đo độ phủ khu vực.',
      c:'Khen từ người xa không giúp chi nhánh Cần Thơ.',
      d:'Đúng. Mục tiêu nhận biết theo vùng, nên đo độ phủ và xem hết đúng vùng.'} },
  ]},

/* ------------------------------------------------------------------ 06 */
{ id:'B:kn04-06', skill:'channel', read:'6 phút', t:'Đăng mỗi ngày hay đăng ít mà chất?',
  situation:'Tuấn làm content cho một spa ở Nha Trang, nghe lời khuyên "phải đăng mỗi ngày" nên ép lịch 2 video TikTok/ngày. Mỗi video anh chỉ còn 1 giờ để làm. Sau một tháng, lượt xem trung bình giảm từ 3.000 xuống 900, anh kiệt sức và tuần thứ năm bỏ đăng luôn 10 ngày.',
  concept:{ name:'Tần suất bền vững',
    body:'Tần suất đúng là mức cao nhất mà bạn <b>giữ được đều đặn</b> mà không hạ chất lượng dưới ngưỡng. Đăng đều giúp khách quen nhịp và nền tảng có đủ bài để học ai thích nội dung của bạn. Nhưng đăng dày mà chất lượng tụt, hoặc dày rồi bỏ ngang, còn tệ hơn nhịp vừa phải mà đều. Cách tính: lấy số giờ thật có mỗi tuần chia cho số giờ cần để làm một bài đạt chuẩn, rồi chừa khoảng trống cho việc phát sinh.' },
  example:'Tuấn có khoảng 12 giờ mỗi tuần cho TikTok. Một video đạt chuẩn (có kịch bản, quay lại khi cần) mất khoảng 3 giờ. 12 ÷ 3 = 4 video, chừa phần dư, anh chọn 3 video/tuần cố định thứ Hai, Tư, Sáu. Sau sáu tuần, lượt xem trung bình quay lại khoảng 2.800 và không có tuần nào bỏ trống.',
  takeaway:'Đều đặn thắng dồn dập: chọn nhịp bạn giữ được cả năm, không phải nhịp bạn cố được một tháng.',
  apply:'Ghi số giờ thật bạn có mỗi tuần và số giờ cho một bài đạt chuẩn. Tính số bài bền vững và nói trong 60 giây.',
  mistakes:['Chép tần suất của một kênh lớn có cả đội sản xuất.','Đăng dày tháng đầu rồi bỏ ngang, làm đứt nhịp khách quen.'],
  q:[
  { type:'mcq', stem:'Đoán trước: vì sao lượt xem của Tuấn giảm dù đăng nhiều gấp đôi?',
    options:[{k:'a',t:'Nền tảng phạt tài khoản đăng quá hai video mỗi ngày'},{k:'b',t:'Khách ở Nha Trang ít dùng TikTok hơn nơi khác'},
             {k:'c',t:'Chất lượng mỗi video tụt, người xem lướt qua nhiều hơn'},{k:'d',t:'Vì đăng dày khiến các video tự cạnh tranh nhau, video sau luôn lấy mất lượt xem của video trước'}],
    answer:'c', why:{a:'Không có dữ kiện cho thấy bị phạt; lượt xem giảm theo chất lượng.',
      b:'Trước đó lượt xem trung bình vẫn 3.000; khán giả không đổi.',
      c:'Đúng. Mỗi video chỉ còn 1 giờ, người xem ít xem hết nên bài được phân phối ít đi.',
      d:'Có thể cạnh tranh nhẹ, nhưng không giải thích việc cả trung bình tụt mạnh.'} },
  { type:'mcq', stem:'Bạn là Tuấn, có 12 giờ/tuần, mỗi video chuẩn mất 3 giờ. Bạn chọn nhịp nào?',
    options:[{k:'a',t:'3 video/tuần vào ngày cố định, chừa khoảng trống'},{k:'b',t:'Quay lại 2 video mỗi ngày nhưng dùng mẫu có sẵn để làm nhanh hơn nữa'},
             {k:'c',t:'1 video/tháng thật đầu tư cho chất lượng tốt nhất'},{k:'d',t:'Đăng khi có cảm hứng, không cố định'}],
    answer:'a', why:{a:'Đúng. Vừa sức, đều, còn thời gian dự phòng.',
      b:'Mẫu có sẵn đẩy nhanh nhưng dễ trùng lặp, chất lượng vẫn thấp.',
      c:'Một video mỗi tháng quá thưa để khách quen nhịp hay nền tảng kịp học.',
      d:'Không cố định thì dễ bỏ trống nhiều tuần.'} },
  { type:'calc', stem:'Một người có 10 giờ/tuần cho content, mỗi bài đạt chuẩn mất 2,5 giờ. Tối đa làm được bao nhiêu bài mỗi tuần?',
    unit:'bài', ans:4, tol:0, wrong:[[25,'NGUOC_TAN_SUAT'],[0.25,'NGUOC_TAN_SUAT']], errors:['NGUOC_TAN_SUAT'],
    steps:['Số bài = giờ có ÷ giờ mỗi bài.','10 ÷ 2,5 = <b>4 bài</b>.'] },
  { type:'mcq', stem:'Một kênh lớn đăng 3 video/ngày. Vì sao chép nguyên nhịp đó thường thất bại với shop nhỏ?',
    options:[{k:'a',t:'Vì kênh lớn được nền tảng ưu ái, còn kênh nhỏ đăng dày sẽ bị giới hạn tiếp cận'},{k:'b',t:'Vì khán giả kênh nhỏ không thích xem nhiều'},
             {k:'c',t:'Vì 3 video/ngày chỉ hợp ngành giải trí'},{k:'d',t:'Vì kênh lớn có cả đội sản xuất; shop nhỏ không giữ nổi chất lượng ở nhịp đó'}],
    answer:'d', why:{a:'Không có cơ chế giới hạn riêng như vậy; nút thắt là nguồn lực.',
      b:'Khán giả xem theo chất lượng, không theo kích cỡ kênh.',
      c:'Ngành nào cũng có thể đăng dày nếu đủ nguồn lực.',
      d:'Đúng. Tần suất phải dựa trên năng lực sản xuất của chính bạn.'} },
  { type:'mcq', stem:'Trang A đăng 20 bài tháng 1, 2 bài tháng 2, 18 bài tháng 3. Trang B đăng đều 10 bài mỗi tháng. Điều gì dễ đúng nhất?',
    options:[{k:'a',t:'Trang A tốt hơn vì tổng số bài trong quý nhiều hơn trang B'},{k:'b',t:'Trang B giữ khách quen nhịp tốt hơn và dễ đọc số liệu hơn'},
             {k:'c',t:'Hai trang như nhau vì cuối cùng khách cũng thấy đủ nội dung'},{k:'d',t:'Trang A tốt hơn vì biến động làm khán giả tò mò'}],
    answer:'b', why:{a:'Tổng nhiều hơn chút nhưng tháng 2 gần như bỏ trống.',
      b:'Đúng. Nhịp đều giúp khách chờ đợi và giúp bạn so sánh các tháng công bằng.',
      c:'Khách không xem bù; bỏ trống thì họ quên.',
      d:'Biến động do bỏ đăng không tạo tò mò, chỉ làm đứt kết nối.'} },
  { type:'mcq', stem:'Khi nào nên tăng tần suất đăng?',
    options:[{k:'a',t:'Khi thấy đối thủ vừa tăng tần suất'},{k:'b',t:'Khi tháng này tiếp cận giảm, cần đăng nhiều hơn để bù lại'},
             {k:'c',t:'Khi đã giữ nhịp cũ đều đặn, có thêm nguồn lực mà chất lượng không tụt'},{k:'d',t:'Khi có ý tưởng hay cần đăng ngay kẻo người khác đăng trước mất cơ hội'}],
    answer:'c', why:{a:'Nguồn lực của đối thủ khác bạn.',
      b:'Tiếp cận giảm thường do chất lượng; đăng dày hơn có thể làm tệ thêm.',
      c:'Đúng. Tăng khi nền đã vững và có năng lực giữ chuẩn.',
      d:'Một ý tưởng hay là đăng một bài, không phải lý do đổi nhịp lâu dài.'} },
  { type:'mcq', stem:'Một tiệm hoa ở Đà Lạt có nhu cầu tăng vọt dịp 8/3 và 20/10. Cách xử lý tần suất nào hợp lý?',
    options:[{k:'a',t:'Giữ nhịp nền đều, chuẩn bị trước bài để tăng nhịp trong vài tuần cao điểm'},{k:'b',t:'Chỉ đăng trong mùa lễ, còn lại nghỉ để tiết kiệm công sức cho những đợt cao điểm lớn'},
             {k:'c',t:'Đăng dày quanh năm như mùa lễ để không bỏ lỡ khách'},{k:'d',t:'Giữ nguyên nhịp suốt năm, kể cả mùa lễ'}],
    answer:'a', why:{a:'Đúng. Nhịp nền giữ khách nhớ; mùa cao điểm tăng có kế hoạch để không tụt chất lượng.',
      b:'Nghỉ dài thì mùa lễ bắt đầu lại từ con số không.',
      c:'Dày quanh năm dễ kiệt sức và thừa nội dung khi nhu cầu thấp.',
      d:'Không tăng mùa lễ là bỏ lỡ lúc khách đang tìm mua nhiều nhất.'} },
  ]},

/* ------------------------------------------------------------------ 07 */
{ id:'B:kn04-07', skill:'channel', read:'6 phút', t:'Một buổi quay có thể thành bao nhiêu bài?',
  situation:'Một thương hiệu đồ da thủ công ở Hà Nội quay một video YouTube 12 phút về quy trình làm ví. Video tốn 10 giờ làm, được 4.000 lượt xem, rồi bị bỏ đó. Mỗi tuần đội lại bắt đầu từ trang trắng cho TikTok, fanpage và Instagram, lúc nào cũng thiếu ý tưởng và thiếu giờ.',
  concept:{ name:'Dùng lại nội dung theo nền tảng',
    body:'Một nội dung gốc có chiều sâu (video dài, bài hướng dẫn, buổi livestream) có thể được <b>cắt và chuyển thể</b> thành nhiều bài cho các nền tảng khác. Chuyển thể không phải đăng lại y hệt: mỗi mảnh phải hợp cách xem nơi đó, như video dọc ngắn có câu mở mạnh cho TikTok, ảnh cuộn nhiều trang cho Instagram, bài chữ cho fanpage, một câu hỏi gợi chuyện cho Threads. Cách này giảm công nghĩ ý tưởng, giữ thông điệp thống nhất, và cho nội dung gốc sống lâu hơn.' },
  example:'Từ video 12 phút, đội cắt ra: 5 clip dọc 30 giây (mỗi clip một công đoạn), 1 bài ảnh cuộn "6 bước làm một chiếc ví", 2 bài fanpage kể chuyện người thợ, 1 tin nhắn Zalo gửi khách cũ. Tổng 9 bài, mất thêm khoảng 6 giờ. Nếu làm từng bài từ đầu, mỗi bài mất khoảng 3 giờ, tức 27 giờ.',
  takeaway:'Làm một nội dung gốc thật chắc, rồi chuyển thể cho từng nền tảng thay vì bắt đầu lại từ trang trắng.',
  apply:'Chọn một video hoặc bài dài bạn đã có. Liệt kê năm mảnh có thể cắt ra, mỗi mảnh ghi nền tảng và định dạng. Nói trong 60 giây.',
  mistakes:['Đăng y hệt một video ngang lên mọi nền tảng.','Cắt clip ngắn mà không có câu mở riêng, người xem không hiểu bối cảnh.'],
  q:[
  { type:'mcq', stem:'Đoán trước: điều gì làm đội đồ da luôn thiếu ý tưởng dù đã có video 12 phút giàu nội dung?',
    options:[{k:'a',t:'Video quá dài nên không ai xem, không đáng dùng tiếp'},{k:'b',t:'Mỗi nền tảng cần nội dung hoàn toàn khác, không dùng chung được'},
             {k:'c',t:'Đội thiếu người sáng tạo, cần tuyển thêm ngay'},{k:'d',t:'Đội coi mỗi bài là một việc riêng, không chuyển thể từ nội dung gốc'}],
    answer:'d', why:{a:'4.000 lượt xem vẫn là tín hiệu; video chứa nhiều cảnh có thể dùng tiếp.',
      b:'Định dạng khác nhau, nhưng cùng một câu chuyện có thể chuyển thể.',
      c:'Thêm người mà giữ cách làm cũ vẫn tốn công bắt đầu từ trang trắng.',
      d:'Đúng. Nội dung gốc bị bỏ phí trong khi nó đủ chất liệu cho cả tuần.'} },
  { type:'mcq', stem:'Bạn phụ trách content tháng tới. Bạn chọn làm gì?',
    options:[{k:'a',t:'Đăng lại nguyên video 12 phút lên TikTok và Instagram mỗi tuần một lần'},{k:'b',t:'Mỗi tháng làm một nội dung gốc, rồi chuyển thể thành các bài hợp từng nền tảng'},
             {k:'c',t:'Tiếp tục làm từng bài riêng nhưng tuyển thêm cộng tác viên để có thêm ý tưởng mỗi tuần'},{k:'d',t:'Bỏ YouTube vì tốn công, chỉ làm clip ngắn'}],
    answer:'b', why:{a:'Video ngang 12 phút không hợp cách xem của TikTok, Instagram.',
      b:'Đúng. Một lần làm sâu, nhiều lần dùng, mỗi mảnh hợp nền tảng.',
      c:'Thêm người làm tăng chi phí mà không giải quyết cách làm kém hiệu quả.',
      d:'Bỏ nội dung gốc là mất nguồn chất liệu cho các clip ngắn.'} },
  { type:'calc', stem:'Làm 9 bài riêng lẻ, mỗi bài 3 giờ. Chuyển thể 9 bài từ video gốc mất thêm 6 giờ. Chuyển thể tiết kiệm bao nhiêu giờ (không tính giờ làm video gốc vì video đã có)?',
    unit:'giờ', ans:21, tol:0, wrong:[[27,'QUEN_CHI_PHI_BIEN_DOI'],[11,'SAI_TINH_TOAN']], errors:['QUEN_CHI_PHI_BIEN_DOI','SAI_TINH_TOAN'],
    steps:['Làm riêng lẻ: 9 × 3 = 27 giờ.','Chuyển thể: 6 giờ.','Tiết kiệm: 27 − 6 = <b>21 giờ</b>.'] },
  { type:'mcq', stem:'Cắt một đoạn từ video dài để đăng TikTok, điều gì cần làm thêm nhất?',
    options:[{k:'a',t:'Thêm câu mở trong 2 giây đầu để người lạ hiểu ngay vì sao nên xem'},{k:'b',t:'Giữ nguyên khung ngang và thêm dòng chữ "xem bản đầy đủ trên YouTube" ở cuối'},
             {k:'c',t:'Tăng tốc độ phát để clip ngắn hơn'},{k:'d',t:'Chèn logo lớn ở giữa khung hình'}],
    answer:'a', why:{a:'Đúng. Người xem TikTok không có bối cảnh của video gốc; câu mở giúp họ dừng lại.',
      b:'Khung ngang hiển thị nhỏ trên màn hình dọc, người xem dễ lướt qua.',
      c:'Tăng tốc làm khó xem, không giải quyết thiếu bối cảnh.',
      d:'Logo lớn che nội dung, không giúp giữ người xem.'} },
  { type:'mcq', stem:'Chuyển thể khác đăng lại y hệt ở điểm nào?',
    options:[{k:'a',t:'Chuyển thể là thêm hashtag khác nhau cho mỗi nền tảng'},{k:'b',t:'Chuyển thể là đăng cùng lúc thay vì đăng lệch ngày giữa các nền tảng khác nhau'},
             {k:'c',t:'Chuyển thể đổi định dạng và cách mở cho hợp nơi đăng, giữ ý chính'},{k:'d',t:'Chuyển thể là thuê người làm lại từ đầu'}],
    answer:'c', why:{a:'Hashtag chỉ là chi tiết nhỏ; bài vẫn lệch khuôn nếu định dạng không đổi.',
      b:'Thời điểm đăng không phải điểm khác cốt lõi.',
      c:'Đúng. Giữ ý, đổi hình thức cho hợp cách xem từng nơi.',
      d:'Làm lại từ đầu là mất lợi ích tiết kiệm công.'} },
  { type:'mcq', stem:'Một chuyên gia tài chính cá nhân vừa livestream 60 phút trả lời câu hỏi. Mảnh nào nên cắt ra cho Threads?',
    options:[{k:'a',t:'Nguyên đoạn livestream 60 phút đăng lại'},{k:'b',t:'Ảnh chụp màn hình lúc livestream có đông người xem nhất để khoe độ phủ của buổi phát'},
             {k:'c',t:'Clip dọc 30 giây có nhạc nền sôi động và hiệu ứng chuyển cảnh'},{k:'d',t:'Một nhận định ngắn gây suy nghĩ kèm câu hỏi mời mọi người trả lời'}],
    answer:'d', why:{a:'Threads chủ yếu là trò chuyện bằng chữ, không hợp video dài.',
      b:'Khoe số người xem không mở ra cuộc trò chuyện nào.',
      c:'Clip dọc hợp TikTok, Reels hơn.',
      d:'Đúng. Threads hợp những ý ngắn mở đường cho người khác tham gia bàn luận.'} },
  { type:'mcq', stem:'Một thương hiệu cắt 20 clip từ một video gốc và đăng hết trong 2 ngày. Rủi ro là gì?',
    options:[{k:'a',t:'Khách thấy lặp dày đặc, nội dung gốc bị vắt kiệt thay vì trải đều'},{k:'b',t:'Nền tảng sẽ khoá tài khoản vì đăng quá nhiều clip có hình ảnh giống nhau'},
             {k:'c',t:'Tiếp cận sẽ cộng dồn theo số clip, nên dồn nhanh là tận dụng tốt nhất'},{k:'d',t:'Video gốc trên YouTube sẽ bị giảm lượt xem ngay'}],
    answer:'a', why:{a:'Đúng. Chuyển thể nên trải theo nhịp; dồn một lúc khiến khách ngán và hết chất liệu cho tuần sau.',
      b:'Khoá tài khoản là lời đồn không chắc chắn; rủi ro rõ hơn là trải nghiệm của khách.',
      c:'Đăng dồn không làm tiếp cận cộng dồn; người xem ngán và lướt qua.',
      d:'Clip ngắn thường còn kéo người về video gốc, không lấy mất lượt xem.'} },
  ]},

/* ------------------------------------------------------------------ 08 */
{ id:'B:kn04-08', skill:'comm', read:'7 phút', t:'Có nên xoá bình luận chê trên fanpage?',
  situation:'Một quán lẩu ở Hải Phòng nhận bình luận dưới bài khuyến mãi: "Hôm qua chờ 45 phút mới có nồi, nhân viên còn cáu." Bình luận có 30 lượt thích và vài người vào đồng tình. Quản lý muốn xoá ngay và chặn tài khoản đó cho "sạch trang".',
  concept:{ name:'Xử lý bình luận tiêu cực công khai',
    body:'Bình luận chê trên fanpage có hai người đọc: người viết và <b>hàng trăm người đang xem</b>. Xoá thường làm người viết giận hơn, chụp màn hình đăng chỗ khác, và người xem thấy quán né tránh. Cách an toàn là phân loại: <b>góp ý thật</b> (trả lời công khai, nhận phần đúng, nêu việc sẽ làm, mời nhắn riêng để giải quyết chi tiết); <b>câu hỏi hiểu lầm</b> (giải thích bình tĩnh); <b>spam, xúc phạm, lộ thông tin cá nhân</b> (ẩn hoặc xoá theo quy tắc trang đã công bố). Trả lời nhanh, không cãi tay đôi, không đổ lỗi cho khách.' },
  example:'Quán trả lời trong 1 giờ: "Quán xin lỗi anh vì phải chờ 45 phút và thái độ chưa tốt. Tối qua quán thiếu hai nhân viên bếp, đó là lỗi sắp xếp của quán. Quán đã bổ sung ca tối từ tuần này. Anh nhắn giúp quán số bàn để quán gửi lại một phần lẩu nhé." Người khách sửa bình luận thành "quán phản hồi nhanh, sẽ quay lại thử". Người đọc sau thấy một quán dám nhận lỗi và sửa.',
  takeaway:'Bình luận chê là sân khấu công khai: trả lời cho người đang xem, không chỉ cho người đã viết.',
  apply:'Tìm một bình luận chê trên fanpage của một thương hiệu, viết câu trả lời ba phần: nhận lỗi, việc sẽ làm, mời nhắn riêng. Đọc to trong 60 giây.',
  mistakes:['Xoá mọi bình luận tiêu cực để trang trông đẹp.','Trả lời bằng lời đổ lỗi cho khách hoặc tranh cãi từng câu.'],
  q:[
  { type:'mcq', stem:'Đoán trước: quản lý xoá bình luận và chặn tài khoản. Điều gì dễ xảy ra?',
    options:[{k:'a',t:'Người khách bức xúc hơn, đăng lại nơi khác kèm ảnh chụp màn hình bị xoá'},{k:'b',t:'Vấn đề kết thúc vì không còn ai thấy bình luận đó trên trang của quán nữa'},
             {k:'c',t:'Người xem khác tin quán hơn vì trang sạch sẽ'},{k:'d',t:'Nền tảng thưởng tiếp cận cho trang không có bình luận xấu'}],
    answer:'a', why:{a:'Đúng. Bị xoá thường làm người khách thấy bị bịt miệng, và câu chuyện lan ra ngoài trang.',
      b:'Người đã đồng tình vẫn nhớ; câu chuyện có thể xuất hiện lại ở nhóm cộng đồng.',
      c:'Người đã thấy bình luận sẽ nhận ra nó biến mất.',
      d:'Không có dữ kiện nền tảng thưởng việc xoá bình luận.'} },
  { type:'mcq', stem:'Bạn là người quản lý fanpage quán lẩu. Bạn làm gì với bình luận này?',
    options:[{k:'a',t:'Ẩn bình luận để người viết và bạn bè họ vẫn thấy, còn người khác không thấy'},{k:'b',t:'Trả lời riêng bằng tin nhắn, không trả lời công khai để tránh ồn ào thêm'},
             {k:'c',t:'Trả lời công khai: xin lỗi, nêu nguyên nhân và việc đã sửa, mời nhắn riêng để bù'},{k:'d',t:'Giải thích dài rằng tối đó quá đông, khách cần thông cảm'}],
    answer:'c', why:{a:'Ẩn góp ý thật vẫn là né tránh; những người đã thấy sẽ nhận ra.',
      b:'Người xem không thấy quán phản hồi, nên vẫn nghĩ quán im lặng.',
      c:'Đúng. Người viết được tôn trọng, người xem thấy quán nhận lỗi và có hành động.',
      d:'Nhấn vào lý do khách phải thông cảm là đẩy lỗi sang khách.'} },
  { type:'calc', stem:'Bình luận chê có 30 lượt thích lúc 8 giờ sáng. Không ai trả lời, mỗi giờ có thêm 6 lượt đồng tình. Nếu quán đợi tới 17 giờ mới trả lời, bình luận đã có bao nhiêu lượt đồng tình?',
    unit:'lượt', ans:84, tol:0, wrong:[[54,'SAI_TINH_TOAN'],[30,'SAI_TINH_TOAN']], errors:['SAI_TINH_TOAN'],
    steps:['Số giờ chờ = 17 − 8 = 9 giờ.','Tăng thêm = 9 × 6 = 54 lượt.','Tổng = 30 + 54 = <b>84 lượt</b>.'] },
  { type:'mcq', stem:'Câu trả lời nào dưới đây có vấn đề nhất?',
    options:[{k:'a',t:'"Quán xin lỗi anh, quán đã bổ sung ca tối. Anh nhắn quán để quán bù nhé."'},{k:'b',t:'"Cảm ơn chị góp ý, quán sẽ kiểm tra camera tối qua và báo lại chị."'},
             {k:'c',t:'"Quán ghi nhận, bếp sẽ giảm muối từ tuần này, mong chị ghé lại."'},{k:'d',t:'"Tối đó đông, ai cũng phải chờ, anh không hài lòng thì có thể sang quán khác."'}],
    answer:'d', why:{a:'Nhận lỗi, nêu việc đã sửa, mời giải quyết riêng; đây là mẫu tốt.',
      b:'Cảm ơn và hứa kiểm tra, có hành động cụ thể; chấp nhận được.',
      c:'Ghi nhận và nêu thay đổi cụ thể; tốt.',
      d:'Đúng. Đổ lỗi cho hoàn cảnh và đuổi khách ngay trước mắt người xem.'} },
  { type:'mcq', stem:'Vì sao nên trả lời bình luận chê trong vòng vài giờ thay vì vài ngày?',
    options:[{k:'a',t:'Vì bình luận sau 24 giờ sẽ bị nền tảng khoá không cho trả lời nữa'},{k:'b',t:'Vì càng để lâu thì người viết càng dễ quên và tự bỏ qua'},
             {k:'c',t:'Vì trả lời nhanh giúp bài được đẩy lên đầu bảng tin của mọi người theo dõi'},{k:'d',t:'Vì trong lúc im lặng, người xem tự kết luận và thêm người vào đồng tình'}],
    answer:'d', why:{a:'Không có giới hạn như vậy.',
      b:'Người bức xúc thường không quên; im lặng dễ làm họ giận thêm.',
      c:'Lý do chính là cảm nhận của người xem, không phải thứ hạng bảng tin.',
      d:'Đúng. Khoảng trống im lặng để cho câu chuyện tự lớn lên theo hướng xấu.'} },
  { type:'mcq', stem:'Một thương hiệu mỹ phẩm bị bình luận "dùng xong nổi mụn". Bước trả lời công khai nào hợp nhất?',
    options:[{k:'a',t:'Hỏi thăm, mời nhắn riêng thông tin sản phẩm, lô hàng để kiểm tra và hỗ trợ'},{k:'b',t:'Khẳng định sản phẩm đã được kiểm nghiệm nên không thể gây mụn'},
             {k:'c',t:'Im lặng vì chuyện da mỗi người mỗi khác'},{k:'d',t:'Gửi ngay mã giảm giá 50% cho lần mua sau để xoa dịu người khách đang bức xúc'}],
    answer:'a', why:{a:'Đúng. Quan tâm trước, rồi thu thông tin để xử lý đúng; không khẳng định hay phủ nhận khi chưa rõ.',
      b:'Phủ nhận thẳng làm khách thấy bị nghi ngờ, người xem thấy hãng cứng nhắc.',
      c:'Im lặng với vấn đề sức khoẻ làm người xem lo hơn.',
      d:'Giảm giá mua tiếp khi khách đang lo về da là lệch trọng tâm.'} },
  { type:'mcq', stem:'Trang nên làm gì trước khi có khủng hoảng bình luận?',
    options:[{k:'a',t:'Tắt bình luận ở mọi bài để phòng xa'},{k:'b',t:'Thuê người viết bình luận khen để lấn át bình luận chê khi xuất hiện trên trang'},
             {k:'c',t:'Công bố quy tắc bình luận và soạn sẵn mẫu trả lời theo từng loại'},{k:'d',t:'Chỉ đăng bài không mở chủ đề gây tranh cãi'}],
    answer:'c', why:{a:'Tắt bình luận mất luôn câu hỏi mua hàng và tín hiệu từ khách.',
      b:'Bình luận khen giả là tương tác ảo, dễ bị phát hiện và phản tác dụng.',
      c:'Đúng. Có quy tắc để xử lý nhất quán, có mẫu để trả lời nhanh mà không lúng túng.',
      d:'Tránh chủ đề nhạy cảm là tốt, nhưng không ngăn được góp ý về dịch vụ.'} },
  ]},

]});
